public final class ClearXPCommand implements CommandExecutor{public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!PermissionManager.has(s,"necromanager.clearxp")){MessageManager.send(s,"messages.no-permission","&cYou do not have permission.");return true;}if(a.length>1){s.sendMessage("Usage: /clearxp [player]");return true;}Player p=a.length==1?Bukkit.getPlayerExact(a[0]):s instanceof Player?(Player)s:null;if(p==null){s.sendMessage(a.length==1?"Player is not online.":"Only players may omit the target.");return true;}p.setExp(0);p.setLevel(0);p.setTotalExperience(0);MessageManager.sendRaw(s,"&aCleared "+p.getName()+"'s experience.");return true;}}
